// Bundles the browser code in webview/ into self-contained HTML strings that
// react-native-webview loads from memory (`source={{ html }}`): no network
// fetch, no file URLs, nothing for the page to navigate to. Run after editing
// webview/*.ts or bumping @xterm/xterm / @novnc/novnc:
//
//   bun run webviews
//
// The generated files are committed (lib/webview/*.generated.ts).
import { join } from "node:path";

const root = join(import.meta.dir, "..");

async function bundle(entry: string): Promise<string> {
  const result = await Bun.build({
    entrypoints: [join(root, "webview", entry)],
    minify: true,
    target: "browser",
    // ESM, not IIFE: noVNC has top-level await.
    format: "esm",
  });
  if (!result.success) throw new Error(`${entry}: ${result.logs.join("\n")}`);
  return result.outputs[0].text();
}

// An inline <script> ends at the first "</script", wherever it appears.
const inlineSafe = (code: string) => code.replace(/<\/(script)/gi, "<\\/$1");

// `__CONNECT_SRC__` is replaced at runtime with the API host's ws(s):// origin.
function page(opts: { connectSrc: string; style: string; body: string; script: string }): string {
  return `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:; connect-src ${opts.connectSrc}">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=6, user-scalable=yes">
<style>${opts.style}</style>
</head>
<body>${opts.body}<script type="module">${inlineSafe(opts.script)}</script></body>
</html>`;
}

const xtermCss = await Bun.file(join(root, "node_modules/@xterm/xterm/css/xterm.css")).text();

const terminal = page({
  // The terminal page never opens a socket; the app owns it.
  connectSrc: "'none'",
  style: `${xtermCss}
html,body{margin:0;background:#0a0a0a;-webkit-user-select:none;user-select:none;-webkit-text-size-adjust:100%}
#wrap{overflow:hidden}
#term{transform-origin:0 0;width:max-content}
.xterm-viewport{display:none}`,
  body: `<div id="wrap"><div id="term"></div></div>`,
  script: await bundle("terminal.ts"),
});

const screen = page({
  connectSrc: "__CONNECT_SRC__",
  style: `html,body{margin:0;height:100%;background:#000;overflow:hidden;overscroll-behavior:none;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
#viewport{position:fixed;inset:0;overflow:hidden}
#screen,#ghost{position:absolute;left:0;top:0}
#ghost{display:none}
#overlay{position:fixed;inset:0;touch-action:none}
#pointer{position:fixed;left:0;top:0;width:26px;height:26px;display:none;pointer-events:none;will-change:transform;z-index:2}
.ripple{position:absolute;width:36px;height:36px;margin:-18px 0 0 -18px;border:3px solid;border-radius:50%;pointer-events:none;animation:ripple .45s ease-out forwards}
@keyframes ripple{from{opacity:.9;transform:scale(.4)}to{opacity:0;transform:scale(1.3)}}`,
  // #pointer: the trackpad pointer, a classic arrow with its tip at (3, 2).
  body: `<div id="viewport"><canvas id="ghost"></canvas><div id="screen"></div></div><div id="overlay"></div><div id="pointer"><svg viewBox="0 0 26 26" width="26" height="26"><path d="M3 2v18.5l4.9-4.6 3.2 7.2 3.3-1.5-3.1-7h6.8z" fill="#fff" stroke="#000" stroke-width="1.5" stroke-linejoin="round"/></svg></div>`,
  script: await bundle("screen.ts"),
});

const out = (name: string, constant: string, html: string) =>
  Bun.write(
    join(root, "lib/webview", name),
    `// Generated by scripts/build-webviews.ts — do not edit.\nexport const ${constant} = ${JSON.stringify(html)};\n`,
  );

await out("terminal-html.generated.ts", "TERMINAL_HTML", terminal);
await out("screen-html.generated.ts", "SCREEN_HTML", screen);
console.log(`terminal ${terminal.length} bytes, screen ${screen.length} bytes`);
